package io.oz.sdoc.docx;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;

import org.junit.jupiter.api.Test;

import io.oz.sdoc.imports.Block;

/**
 * Facts of hello/docx4j's samples/tricky.docx (generated by its gen_sample.py),
 * the same as FactsDemo prints in its README.
 */
class DocxWalkerTest {

	@Test
	void tricky() throws Exception {
		List<Block> blocks = DocxWalker.blocks("src/test/res/tricky.docx");

		// "src kind style outline num text"
		assertArrayEquals(new String[] {
			"body/0 p Title -1 null Annual Report",
			"body/1 p 章标题 0 null 第一章 总则",
			"body/2 p Normal null null Body text under chapter one.",
			"body/3 p heading 2 1 null 1.1 Scope",
			"body/4 p Normal 1 null Direct outline level on a Normal paragraph",
			"body/5 p Clause 2 null Clause 7: confidentiality",
			"body/6 p List Number null 1. First bullet",
			"body/7 p List Number null 2. Second bullet",
			"body/8 table null null null merged header {colspan=2} | r0c2 // r1c0 | r1c1 | vertical merge {vmerge-start} // r2c0 | r2c1 |  {vmerge-cont}",
			"body/9/sdt/0 p heading 1 0 null 第二章 Inside a content control",
			"body/10 p Normal null null Body text under chapter two.",
		}, blocks.stream().map(b -> String.join(" ", b.src, b.kind, String.valueOf(b.styleName),
				String.valueOf(b.outline), String.valueOf(b.numLabel), b.text)).toArray(String[]::new));

		assertTrue(blocks.get(8).hasSpans);
	}
}
